package com.documind.extraction;

import com.documind.common.BaseEntity;
import com.documind.template.FieldDataType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * One business field of a document, prepared from a template and filled by a
 * human or a future extraction pipeline. Values are never generated by the
 * platform itself.
 */
@Entity
@Table(name = "extracted_fields")
public class ExtractedFieldEntity extends BaseEntity {

    @Column(name = "workspace_id", nullable = false)
    private UUID workspaceId;

    @Column(name = "document_id", nullable = false)
    private UUID documentId;

    @Column(name = "template_field_id")
    private UUID templateFieldId;

    @Column(name = "field_name", nullable = false, length = 80)
    private String fieldName;

    @Column(name = "field_label", nullable = false, length = 140)
    private String fieldLabel;

    @Enumerated(EnumType.STRING)
    @Column(name = "data_type", nullable = false, length = 20)
    private FieldDataType dataType;

    @Column(name = "field_value", length = 2000)
    private String value;

    @Column(name = "original_value", length = 2000)
    private String originalValue;

    @Column(precision = 5, scale = 2)
    private BigDecimal confidence;

    @Column(name = "source_page")
    private Integer sourcePage;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private ExtractionFieldStatus status = ExtractionFieldStatus.PENDING;

    @Column(name = "edited_by")
    private UUID editedBy;

    @Column(name = "edited_at")
    private Instant editedAt;

    @Column(name = "created_by")
    private UUID createdBy;

    protected ExtractedFieldEntity() {
    }

    public ExtractedFieldEntity(UUID workspaceId, UUID documentId, UUID templateFieldId,
            String fieldName, String fieldLabel, FieldDataType dataType, UUID createdBy) {
        this.workspaceId = workspaceId;
        this.documentId = documentId;
        this.templateFieldId = templateFieldId;
        this.fieldName = fieldName;
        this.fieldLabel = fieldLabel;
        this.dataType = dataType;
        this.status = ExtractionFieldStatus.PENDING;
        this.createdBy = createdBy;
    }

    public UUID getWorkspaceId() {
        return workspaceId;
    }

    public UUID getDocumentId() {
        return documentId;
    }

    public UUID getTemplateFieldId() {
        return templateFieldId;
    }

    public String getFieldName() {
        return fieldName;
    }

    public String getFieldLabel() {
        return fieldLabel;
    }

    public FieldDataType getDataType() {
        return dataType;
    }

    public String getValue() {
        return value;
    }

    public String getOriginalValue() {
        return originalValue;
    }

    public BigDecimal getConfidence() {
        return confidence;
    }

    public Integer getSourcePage() {
        return sourcePage;
    }

    public ExtractionFieldStatus getStatus() {
        return status;
    }

    public UUID getEditedBy() {
        return editedBy;
    }

    public Instant getEditedAt() {
        return editedAt;
    }

    public UUID getCreatedBy() {
        return createdBy;
    }

    public void updateValue(String newValue, UUID editorId) {
        if (this.originalValue == null) {
            // Keep the first known value so the change history stays auditable.
            this.originalValue = this.value;
        }
        this.value = newValue;
        this.status = newValue == null ? ExtractionFieldStatus.PENDING : ExtractionFieldStatus.EDITED;
        this.editedBy = editorId;
        this.editedAt = Instant.now();
    }

    public void validateValue(UUID editorId) {
        this.status = ExtractionFieldStatus.VALIDATED;
        this.editedBy = editorId;
        this.editedAt = Instant.now();
    }

    public void reopen(UUID editorId) {
        this.status = this.value == null ? ExtractionFieldStatus.PENDING : ExtractionFieldStatus.EDITED;
        this.editedBy = editorId;
        this.editedAt = Instant.now();
    }
}
